```rust
use lazy_static::lazy_static;

lazy_static! {
    // Global static DB pool and config
    pub static ref DB_POOL: sqlx::Pool<Postgres> = sqlx::Pool::connect_lazy("...").unwrap();
    static ref GLOBAL_CONFIG: Mutex<Config> = Mutex::new(Config::default());
}

struct Connection { host: String }
impl Connection {
    fn new() -> Self {
        // Constructor silently resolves configuration from global state
        let host = GLOBAL_CONFIG.lock().unwrap().host.clone();
        Self { host }
    }
}

pub fn update_user_status(id: u64, status: &str) {
    // Domain function directly accesses the global pool
    let _ = DB_POOL.execute(format!("UPDATE users SET status = '{}' WHERE id = {}", status, id));
}
```

fix:
Utilize dependency injection. Pass the connection pool reference `&Pool` explicitly into the function signature or supply it as a field during struct construction, and pass required configuration directly into constructors and builders. Keep global resolution at the composition boundary rather than inside business behavior; existing explicit framework injection may be retained.
```rust
impl Connection {
    fn new(config: &Config) -> Self {
        Self { host: config.host.clone() }
    }
}

pub fn update_user_status(pool: &sqlx::Pool<Postgres>, id: u64, status: &str) {
    let _ = pool.execute(/* ... */);
}
